spec fn small(x: i64) -> bool { -1000000000 <= x && x <= 1000000000 }

spec fn is_sum(a: i64, b: i64, r: i64) -> bool { r == a + b }

#[effects(pure)]
#[uses(small, is_sum)]
fn add(a: i64, b: i64) -> (r: i64)
    requires small(a),
    ensures is_sum(a, b, r),
{
    0
}

