#[summary("impossibility certificate")]
mod bmb_cert {
    spec fn never() -> bool { false }

    spec fn witness(a: i64, b: i64) -> bool { a == 1 && b == 9223372036854775807 }

    #[effects(pure)]
    #[uses(witness, tasks::small, tasks::is_sum)]
    fn refute(a: i64, b: i64) -> ()
        requires witness(a, b),
        ensures never(),
    {
        let r: i64 = tasks::add(a, b);
    }

    #[effects(pure)]
    #[uses(witness)]
    fn reach() -> () {
        refute(1, 9223372036854775807)
    }
}

